package gen:node;

world node {
    use aap:caps/types@0.1.0.{moderated-query, conversation-context};

    import aap:caps/kb-read@0.1.0;

    export run: func(query: moderated-query) -> conversation-context;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

const MAX_QUESTION_CHARS: usize = 512;

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let question = bound_chars(query.query.question, MAX_QUESTION_CHARS);
        let knowledge = kb_read::lookup(&question);
        ConversationContext {
            intent: query.query.intent,
            question,
            knowledge,
        }
    }
}

/// Truncates to at most `max` Unicode scalar values, matching Python's `len`
/// on `str`, and never splits a character.
fn bound_chars(s: String, max: usize) -> String {
    if s.chars().count() <= max {
        s
    } else {
        s.chars().take(max).collect()
    }
}

export!(Node);
